INSERT INTO `wp_posts` VALUES (22,1,'2022-07-02 00:31:35','2022-07-02 04:31:35','<form action=\"\" method=\"post\"  >\n	<p>\n		<label for=\"account_first_name\">First name&nbsp;*</label>\n		<input type=\"text\" name=\"account_first_name\" id=\"account_first_name\" autocomplete=\"given-name\" value=\"ClimaxThemes\" />\n	</p>\n	<p>\n		<label for=\"account_last_name\">Last name&nbsp;*</label>\n		<input type=\"text\" name=\"account_last_name\" id=\"account_last_name\" autocomplete=\"family-name\" value=\"\" />\n	</p>\n	<p>\n		<label for=\"account_display_name\">Display name&nbsp;*</label>\n		<input type=\"text\" name=\"account_display_name\" id=\"account_display_name\" value=\"ClimaxThemes\" /> <em>This will be how your name will be displayed in the account section and in reviews</em>\n	</p>\n	<p>\n		<label for=\"account_email\">Email address&nbsp;*</label>\n		<input type=\"email\" name=\"account_email\" id=\"account_email\" autocomplete=\"email\" value=\"demos@katademos.com\" />\n	</p>\n	<fieldset>\n		<legend>Password change</legend>\n		<p>\n			<label for=\"password_current\">Current password (leave blank to leave unchanged)</label>\n			<input type=\"password\" name=\"password_current\" id=\"password_current\" autocomplete=\"off\" />\n		</p>\n		<p>\n			<label for=\"password_1\">New password (leave blank to leave unchanged)</label>\n			<input type=\"password\" name=\"password_1\" id=\"password_1\" autocomplete=\"off\" />\n		</p>\n		<p>\n			<label for=\"password_2\">Confirm new password</label>\n			<input type=\"password\" name=\"password_2\" id=\"password_2\" autocomplete=\"off\" />\n		</p>\n	</fieldset>\n	<p>\n		<input type=\"hidden\" id=\"save-account-details-nonce\" name=\"save-account-details-nonce\" value=\"5798bb6fef\" /><input type=\"hidden\" name=\"_wp_http_referer\" value=\"/shoppress/demo/wp-admin/admin-ajax.php\" />		<button type=\"submit\" name=\"save_account_details\" value=\"Save changes\">Save changes</button>\n		<input type=\"hidden\" name=\"action\" value=\"save_account_details\" />\n	</p>\n	</form>','My Account','','publish','closed','closed','','my-account','','','2022-07-02 00:31:35','2022-07-02 04:31:35','',0,'http://js-auto-decor.local/?p=22',0,'shoppress_myaccount','',0);
