INSERT INTO `wp_posts` VALUES (52,1,'2026-09-10 00:53:19','2026-09-10 00:53:19','<label> Your name\n    [text* your-name autocomplete:name] </label>\n\n<label> Your email\n    [email* your-email autocomplete:email] </label>\n\n<label> Subject\n    [text* your-subject] </label>\n\n<label> Your message (optional)\n    [textarea your-message] </label>\n\n[submit \"Submit\"]\n[_site_title] \"[your-subject]\"\n[_site_title] <wordpress@js-auto-decor.local>\nFrom: [your-name] [your-email]\nSubject: [your-subject]\n\nMessage Body:\n[your-message]\n\n-- \nThis is a notification that a contact form was submitted on your website ([_site_title] [_site_url]).\n[_site_admin_email]\nReply-To: [your-email]\n\n0\n0\n\n[_site_title] \"[your-subject]\"\n[_site_title] <wordpress@js-auto-decor.local>\nMessage Body:\n[your-message]\n\n-- \nThis email is a receipt for your contact form submission on our website ([_site_title] [_site_url]) in which your email address was used. If that was not you, please ignore this message.\n[your-email]\nReply-To: [_site_admin_email]\n\n0\n0\nThank you for your message. It has been sent.\nThere was an error trying to send your message. Please try again later.\nOne or more fields have an error. Please check and try again.\nThere was an error trying to send your message. Please try again later.\nYou must accept the terms and conditions before sending your message.\nPlease fill out this field.\nThis field has a too long input.\nThis field has a too short input.\nThere was an unknown error uploading the file.\nYou are not allowed to upload files of this type.\nThe uploaded file is too large.\nThere was an error uploading the file.','Contact form 1','','publish','closed','closed','','contact-form-1','','','2026-09-10 00:53:19','2026-09-10 00:53:19','',0,'http://js-auto-decor.local/?post_type=wpcf7_contact_form&p=52',0,'wpcf7_contact_form','',0);
INSERT INTO `wp_posts` VALUES (53,1,'2022-07-02 01:30:18','2022-07-02 05:30:18','<h2 >ShopPress Store</h2>\n							<h1 >click to get\nbest quality\nproducts.</h1>\n					<a href=\"/shop\"  >\n		<i>\n<svg version=\"1.1\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" width=\"17\" height=\"17\" viewBox=\"0 0 17 17\">\r<g>\r</g>\r	<path d=\"M6.854 4.146l4.353 4.354-4.354 4.354-0.707-0.707 3.647-3.647-3.647-3.646 0.708-0.708zM17 8.5c0 4.687-3.813 8.5-8.5 8.5s-8.5-3.813-8.5-8.5 3.813-8.5 8.5-8.5 8.5 3.813 8.5 8.5zM16 8.5c0-4.136-3.364-7.5-7.5-7.5s-7.5 3.364-7.5 7.5 3.364 7.5 7.5 7.5 7.5-3.364 7.5-7.5z\" fill=\"#000000\" />\r</svg>\r</i>	All Products\n		</a>\n	<figure>\n		<a href=\"#\"  ></a>						<h3 >Plants </h3>From $9.00		\n		<img width=\"406\" height=\"312\" src=\"http://js-auto-decor.local/wp-content/uploads/2022/08/shoppress-demo-banner7.png\" alt=\"\" decoding=\"async\" srcset=\"http://js-auto-decor.local/wp-content/uploads/2022/08/shoppress-demo-banner7.png 406w, http://js-auto-decor.local/wp-content/uploads/2022/08/shoppress-demo-banner7-300x231.png 300w, http://js-auto-decor.local/wp-content/uploads/2022/08/shoppress-demo-banner7-20x15.png 20w\" sizes=\"(max-width: 406px) 100vw, 406px\" />\n			</figure>\n	<figure>\n		<a href=\"#\"  ></a>						<h3 >Cosmetics</h3>From $5.00		\n		<img width=\"406\" height=\"312\" src=\"http://js-auto-decor.local/wp-content/uploads/2022/08/shoppress-demo-banner6.png\" alt=\"\" decoding=\"async\" srcset=\"http://js-auto-decor.local/wp-content/uploads/2022/08/shoppress-demo-banner6.png 406w, http://js-auto-decor.local/wp-content/uploads/2022/08/shoppress-demo-banner6-300x231.png 300w, http://js-auto-decor.local/wp-content/uploads/2022/08/shoppress-demo-banner6-20x15.png 20w\" sizes=\"(max-width: 406px) 100vw, 406px\" />\n			</figure>\n	<figure>\n		<a href=\"#\"  ></a>						<h3 >Decors</h3>From $6.00		\n		<img width=\"406\" height=\"312\" src=\"http://js-auto-decor.local/wp-content/uploads/2022/08/shoppress-demo-banner5.png\" alt=\"\" decoding=\"async\" srcset=\"http://js-auto-decor.local/wp-content/uploads/2022/08/shoppress-demo-banner5.png 406w, http://js-auto-decor.local/wp-content/uploads/2022/08/shoppress-demo-banner5-300x231.png 300w, http://js-auto-decor.local/wp-content/uploads/2022/08/shoppress-demo-banner5-20x15.png 20w\" sizes=\"(max-width: 406px) 100vw, 406px\" />\n			</figure>\n							<h2 >Featured Products</h2>\n			<ul>\n<li>\n	<style id=\"styler-e9010cc\">.elementor-element.elementor-element-e9010cc{margin-top:22px;margin-right:auto;margin-left:auto;}\n</style><style id=\"styler-66e4f509\">.elementor-element.elementor-element-66e4f509 .sp-loop-rating.sp-modern-rating .sp-rating .sp-rating-star{font-size:14px;color:#ffb000;}\n.elementor-element.elementor-element-66e4f509 .sp-loop-rating.sp-modern-rating .sp-rating{background-color:#FFFFFF;border-style:solid;border-width:1px;border-color:#e3e5e7;width:59px;height:30px;line-height:1em;padding-top:6px;padding-right:0px;padding-bottom:5px;padding-left:0px;font-size:15px;font-family: Be Vietnam Pro,sans-serif;color:#1e354e;border-radius:6px;text-align:center;}\n</style><style id=\"styler-6b84ca19\">.elementor-element.elementor-element-6b84ca19{text-align:right;width:35% !important;}\n</style><style id=\"styler-2181d6ca\">.elementor-element.elementor-element-2181d6ca .sp-product-price .price{color:#737d8b;}\n.elementor-element.elementor-element-2181d6ca .sp-product-price .price span.woocommerce-Price-amount.amount{font-size:16px;font-weight:400;line-height:1.37em;color:#737d8b;}\n.elementor-element.elementor-element-2181d6ca .sp-product-price .price del span.woocommerce-Price-amount.amount{font-size:16px;font-weight:400;line-height:1.37em;color:#737d8b;}\n</style><style id=\"styler-2639cd4d\">.elementor-element.elementor-element-2639cd4d .sp-product-title{padding-top:0px !important;padding-bottom:0px !important;font-size:17px !important;line-height:22px;font-weight:500;color:#4C5765;margin-bottom:7px !im