INSERT INTO `wp_posts` VALUES (423,1,'2022-07-04 01:23:50','2022-07-04 05:23:50','<h2 >Get in Touch.</h2>\n							<p >Are you willing to enhance your business and find the best solution ? We are here to help.</p>\n							<h5 >Address</h5>\n							<p >163 Hilario Court Stokeston, AB P0E3T1, CA</p>\n							<h5 >Phone</h5>\n							<p >(062) 109-9222</p>\n<p role=\"status\" aria-live=\"polite\" aria-atomic=\"true\"></p> <ul></ul>\n<form action=\"/shop/wp-admin/admin-ajax.php#wpcf7-f421-o1\" method=\"post\" aria-label=\"Contact form\" novalidate=\"novalidate\" data-status=\"init\">\n<input type=\"hidden\" name=\"_wpcf7\" value=\"421\" />\n<input type=\"hidden\" name=\"_wpcf7_version\" value=\"6.0\" />\n<input type=\"hidden\" name=\"_wpcf7_locale\" value=\"en_CA\" />\n<input type=\"hidden\" name=\"_wpcf7_unit_tag\" value=\"wpcf7-f421-o1\" />\n<input type=\"hidden\" name=\"_wpcf7_container_post\" value=\"0\" />\n<input type=\"hidden\" name=\"_wpcf7_posted_data_hash\" value=\"\" />\n		<p><label> Your Name<br />\n<input size=\"40\" maxlength=\"400\" aria-required=\"true\" aria-invalid=\"false\" placeholder=\"John Smith\" value=\"\" type=\"text\" name=\"your-name\" /> </label>\n		</p>\n		<p><label> Your Email<br />\n<input size=\"40\" maxlength=\"400\" aria-required=\"true\" aria-invalid=\"false\" placeholder=\"info@example.com\" value=\"\" type=\"email\" name=\"your-email\" /> </label>\n		</p>\n		<p><label> Subject<br />\n<input size=\"40\" maxlength=\"400\" aria-invalid=\"false\" placeholder=\"My Project\" value=\"\" type=\"text\" name=\"your-subject\" /> </label>\n		</p>\n		<p><label> Your Message<br />\n<textarea cols=\"40\" rows=\"10\" maxlength=\"2000\" aria-invalid=\"false\" placeholder=\"Hello, ...\" name=\"your-message\"></textarea> </label>\n		</p>\n		<p><input type=\"submit\" value=\"Submit\" />\n		</p>\n</form>','Contact','','publish','closed','closed','','contact','','','2022-07-04 01:23:50','2022-07-04 05:23:50','',0,'http://js-auto-decor.local/?page_id=423',0,'