INSERT INTO `wp_posts` VALUES (461,1,'2022-07-04 02:09:43','2022-07-04 06:09:43','<img width=\"528\" height=\"416\" src=\"http://js-auto-decor.local/wp-content/uploads/2022/07/kata-shoppress-track-image.png\" alt=\"\" decoding=\"async\" srcset=\"http://js-auto-decor.local/wp-content/uploads/2022/07/kata-shoppress-track-image.png 528w, http://js-auto-decor.local/wp-content/uploads/2022/07/kata-shoppress-track-image-300x236.png 300w\" sizes=\"(max-width: 528px) 100vw, 528px\" />			\n							<h2 >Track Your Order</h2>\n	<form action=\"http://js-auto-decor.local/track-order/\" method=\"post\">\n					<p>To track your order please enter your Order ID in the box below and press the &quot;Track&quot; button. This was given to you on your receipt and in the confirmation email you should.</p>\n		<p>\n			<label for=\"orderid\">Order ID</label>\n			<input type=\"text\" name=\"orderid\" id=\"orderid\" value=\"\" placeholder=\"Found in your order confirmation email.\" />\n        </p>\n		<p>\n			<label for=\"order_email\">Billing email</label>\n			<input type=\"text\" name=\"order_email\" id=\"order_email\" value=\"\" placeholder=\"Email you used during checkout.\" />\n        </p>		\n		<p>\n			<button type=\"submit\" name=\"track\" value=\"Track\">Track</button>\n		</p>\n		<input type=\"hidden\" id=\"woocommerce-order-tracking-nonce\" name=\"woocommerce-order-tracking-nonce\" value=\"6eb0f768b7\" /><input type=\"hidden\" name=\"_wp_http_referer\" value=\"/shop/wp-admin/admin-ajax.php\" />	</form>','Track Order','','publish','closed','closed','','track-order','','','2022-07-04 02:09:43','2022-07-04 06:09:43','',0,'http://js-auto-decor.local/?page_id=461',0,'page','',0);
