INSERT INTO `wp_posts` VALUES (2999,1,'2026-09-10 00:55:04','2026-09-10 00:55:04','@media screen and (max-width: 1024px) {\n    .woocommerce ul.products.columns-4 li.product {\n        width: calc(100% / 2 - 30px);\n    }\n}\n\na.added_to_cart.wc-forward {\n	display:none\n}\n\ndiv#wc-stripe-payment-request-wrapper, p#wc-stripe-payment-request-button-separator {\n    display: none;\n}\n\n.filter-toggle .shop-press-header-toggle-click:hover:before {\n    background-image: url(\'data:image/svg+xml;base64,\');\n}\n\n.shop-press-header-toggle.dropdown .shop-press-header-toggle-content-wrap {\n    left: 0 !important;\n	  right: unset !important;\n    transition: left .5s ease !important;\n}\n\n.shop-press-header-toggle.dropdown .shop-press-header-toggle-click:not(.active) + .shop-press-header-toggle-content-wrap {\n    left: -1000px !important;\n	  right: unset !important;\n}\n\n.shop-press-header-toggle.dropdown .shop-press-header-toggle-content-wrap::-webkit-scrollbar {\n    width: 4px;\n}\n\n.shop-press-header-toggle.dropdown .shop-press-header-toggle-content-wrap::-webkit-scrollbar-track {\n    border-radius: 2px;\n	  background: #fff;\n}\n\n.shop-press-header-toggle.dropdown .shop-press-header-toggle-content-wrap::-webkit-scrollbar-thumb {\n    border-radius: 2px;\n    background: #E3E5E7;\n}\n\n.wishlist-box .sp-my-wishlist-empty {\n    text-align: center\n}\n\n.wishlist-box .sp-my-wishlist-empty h2 {\n    font-size: 15px;\n    font-weight: 400;\n}\n\n.wishlist-box .sp-my-wishlist-empty a {\n    font-size: 15px;\n    font-weight: 400;\n    padding: 0;\n}\n\n.wishlist-box .sp-my-wishlist-empty a:hover {\n    background: none;\n}\n\n.woocommerce-page form.login, .woocommerce-page form.register {\n    max-width: 475px;\n    margin: 0 auto;\n}\n\n.shop-press-header-toggle-close svg path {\n    transition: .2s ease;\n}\n.shop-press-header-toggle-close:hover svg path {\n    fill: red;\n}\n\n.sp-products-loop-wrapper p.woocommerce-info.woocommerce-no-products-found {\n    margin-top: 50px\n}\n\n.sp-sidebar.sp-product-filters .sp-reset-filters {\n    top: -56px;\n}\n\n\n.sp-product-remove-item svg path {\n	transition: 200ms;\n}\n\n.sp-product-remove-item svg:hover path {\n	fill: #fff;\n}\n\nbody {\ncolor:#737D8B;\nfont-family:\'Be Vietnam Pro\',Arial,Roboto,Sans-serif\n}','kata','','publish','closed','closed','','kata','','','2026-09-10 00:55:04','2026-09-10 00:55:04','',0,'http://js-auto-decor.local/kata/',0,'custom_css','',0);
